import { prisma } from "@/src/lib/prisma";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import { Activity, Zap, Target, Box, Layout } from "lucide-react";
import { getServerSession } from "next-auth";
import { authOptions } from "@/app/api/auth/[...nextauth]/route"; 
import { redirect } from "next/navigation";
import { UserMenu } from "components/user-menu"; // Senin mevcut butonun/menün

// 1. TypeScript kırmızılığını (id hatasını) bitiren interface
interface CustomSession {
  user: {
    id: string;
    email?: string | null;
    name?: string | null;
  };
}

export default async function DashboardPage() {
  // 2. Session'ı al ve CustomSession tipine zorla
  const session = (await getServerSession(authOptions)) as CustomSession | null;

  // 3. GÜVENLİK: Oturum yoksa içeri sokma
  if (!session || !session.user) {
    redirect("/auth/signin");
  }

  // 4. VERİ FİLTRELEME: Sadece bu kullanıcıya (session.user.id) ait verileri çek
  const allTasks = await prisma.task.findMany({ 
    where: {
      userId: session.user.id 
    },
    orderBy: { createdAt: 'desc' } 
  });

  // VERİ ANALİZİ
  const latestTask = allTasks[0];
  let activeSprint = "1";
  if (latestTask) {
    try { 
      activeSprint = JSON.parse(latestTask.description || "{}").sprint || "1"; 
    } catch { 
      activeSprint = "1"; 
    }
  }

  const activeSprintTasks = allTasks.filter(task => {
    try { 
      return JSON.parse(task.description || "{}").sprint === activeSprint; 
    } catch { 
      return false; 
    }
  }).map(task => {
    try {
      const data = JSON.parse(task.description || "{}");
      const checkFields: Record<string, string[]> = {
        review: ['geleerd', 'nietVoldoende', 'actiepunten'],
        retrospective: ['goed', 'beter', 'actiepunt'],
        daily: ['klaar', 'planningStatus', 'obstakels'],
        sprintplan: ['backlog', 'todo', 'dod']
      };
      const fields = checkFields[data.documentType] || [];
      const filled = fields.filter(f => data[f] && String(data[f]).trim().length > 0).length;
      const percentage = fields.length > 0 ? Math.round((filled / fields.length) * 100) : 0;
      return { ...task, data, percentage };
    } catch {
      return { ...task, data: {}, percentage: 0 };
    }
  });

  const totalPercentage = activeSprintTasks.length > 0
    ? Math.round(activeSprintTasks.reduce((acc, curr) => acc + curr.percentage, 0) / activeSprintTasks.length)
    : 0;

  return (
    <div className="min-h-screen bg-[#02040a] text-slate-200 p-6 font-sans selection:bg-fuchsia-500/30">
      <div className="max-w-[1600px] mx-auto">
        
        {/* HEADER */}
        <div className="flex justify-between items-center mb-10">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-fuchsia-600 flex items-center justify-center shadow-[0_0_20px_#d946ef]">
              <Layout className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-2xl font-black tracking-tighter uppercase italic text-white leading-none">Neuro-Interface v4.0</h1>
              <p className="text-[10px] text-teal-400 font-mono tracking-[0.3em] mt-1 uppercase">
                Operator: {session.user.email?.split('@')[0]}  Status: Secure
              </p>
            </div>
          </div>
          
          <div className="flex items-center gap-6">
            {/* Senin mevcut çıkış butonun/menün */}
            <UserMenu /> 
            
            <Link href="/tasks">
              <Button className="bg-transparent border-2 border-fuchsia-600 text-fuchsia-500 hover:bg-fuchsia-600 hover:text-white font-black px-8 py-6 transition-all duration-300 rounded-none uppercase tracking-widest text-xs shadow-[inset_0_0_10px_rgba(217,70,239,0.2)]">
                + Initialize New Log
              </Button>
            </Link>
          </div>
        </div>

        {/* DASHBOARD GRID */}
        <div className="grid grid-cols-12 gap-6">
          <div className="col-span-12 lg:col-span-4 bg-[#0a0e17] border border-white/5 p-8 relative flex flex-col items-center justify-center min-h-[450px]">
             <div className="absolute top-4 left-4 flex items-center gap-2 text-[10px] font-black text-teal-500 uppercase tracking-widest">
                <Activity size={14} /> Global Sprint Completion
             </div>
             <div className="relative w-64 h-64">
                <svg className="w-full h-full -rotate-90" viewBox="0 0 100 100">
                  <circle cx="50" cy="50" r="45" fill="transparent" stroke="rgba(20, 184, 166, 0.1)" strokeWidth="8" />
                  <circle cx="50" cy="50" r="45" fill="transparent" stroke="#d946ef" strokeWidth="8" strokeDasharray="282.7" strokeDashoffset={282.7 - (282.7 * totalPercentage) / 100} strokeLinecap="round" style={{ filter: "drop-shadow(0 0 8px #d946ef)" }} />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <span className="text-6xl font-black text-white italic">{totalPercentage}%</span>
                  <span className="text-[10px] text-teal-500 font-bold tracking-widest uppercase mt-[-5px]">Sprint {activeSprint}</span>
                </div>
             </div>
          </div>

          <div className="col-span-12 lg:col-span-8 bg-[#0a0e17] border border-white/5 p-8">
            <div className="flex justify-between items-center mb-8">
                <h2 className="text-sm font-black uppercase italic tracking-widest flex items-center gap-2">
                    <Target className="text-fuchsia-500" size={16} /> Active Log Analysis
                </h2>
                <span className="text-[10px] font-mono text-white/30 tracking-widest">{activeSprintTasks.length} NODES</span>
            </div>
            <div className="space-y-6 overflow-y-auto max-h-[400px] pr-4 custom-scrollbar">
              {activeSprintTasks.length > 0 ? (
                activeSprintTasks.map((task) => (
                  <div key={task.id} className="group relative">
                    <div className="flex justify-between items-end mb-2">
                      <div className="flex items-center gap-3">
                        <div className={`w-2 h-2 rounded-full ${task.percentage === 100 ? 'bg-teal-400' : 'bg-fuchsia-500 animate-pulse'}`} />
                        <span className="text-xs font-bold text-white group-hover:text-fuchsia-400 uppercase">{task.title}</span>
                      </div>
                      <span className="text-xs font-black italic text-teal-400">{task.percentage}%</span>
                    </div>
                    <div className="h-1 w-full bg-white/5 overflow-hidden">
                      <div className={`h-full transition-all duration-700 ${task.percentage === 100 ? 'bg-teal-400' : 'bg-fuchsia-500'}`} style={{ width: `${task.percentage}%` }} />
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-center text-white/20 text-xs italic tracking-widest py-10">NO DATA FOUND FOR THIS OPERATOR</p>
              )}
            </div>
          </div>

          {/* GERİ GELEN ALT KARTLAR */}
          <div className="col-span-12 grid grid-cols-1 md:grid-cols-4 gap-6">
             {[
               { label: "Data Integrity", val: "100%", icon: Zap, color: "text-teal-400" },
               { label: "User Nodes", val: activeSprintTasks.length, icon: Box, color: "text-fuchsia-500" },
               { label: "Sprint Cycle", val: `S-${activeSprint}`, icon: Target, color: "text-white" },
               { label: "Uptime", val: "24/7", icon: Activity, color: "text-teal-400" }
             ].map((stat, i) => (
               <div key={i} className="bg-[#0a0e17] border border-white/5 p-5 flex items-center justify-between group hover:bg-white/[0.02] transition-all">
                  <div>
                    <p className="text-[9px] font-black uppercase tracking-[0.2em] text-white/40 mb-1">{stat.label}</p>
                    <p className={`text-xl font-black italic ${stat.color}`}>{stat.val}</p>
                  </div>
                  <stat.icon className="text-white/5 group-hover:text-white/20 transition-colors" size={32} />
               </div>
             ))}
          </div>
        </div>
      </div>
      
      {/* CRT SCANLINE EFFECT */}
      <div className="fixed inset-0 pointer-events-none border-[20px] border-[#02040a] z-50 opacity-10">
        <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_2px,3px_100%]" />
      </div>
    </div>
  );
}